"""
    Creates tasks to be run against the NasApi

    It creates tasks for each year in the input years."
    """
def create_tasks(job_id: Any, years: Any, finished_year: Any) -> object {
    next_year = finished_year;
    for year in years.split(',') {
        if not next_year {
            next_year = year;
            break;
        }
        if (year == next_year) {
            next_year = None;
        }
    }
    tasks = [];
    if next_year {
        tasks.append(
            {
                'job_id': job_id,
                'years': years,
                'year': next_year,
                'calc_type': 'mean',
                'quantile': ''
            }
        );
        tasks.append(
            {
                'job_id': job_id,
                'years': years,
                'year': next_year,
                'calc_type': 'quantile',
                'quantile': '90'
            }
        );
        tasks.append(
            {
                'job_id': job_id,
                'years': years,
                'year': next_year,
                'calc_type': 'quantile',
                'quantile': '10'
            }
        );
    }
    return tasks;
}

